#include<cstdio>
#include<algorithm>
#include<cmath>
#include<cstring>
using namespace std;inline int read(){int x=0;char c=getchar();while(c<'0'||c>'9')c=getchar();while(c>='0'&&c<='9')x=x*10+(c^48),c=getchar();return x;}typedef long long ll;const int N=200005,M=200005,B=450;int n,m,rt;int h[N],to[N<<1],nx[N<<1],en;int fa[N],sz[N],dfn[N],out[N],tim,id[N];void add(int u,int v){to[++en]=v;nx[en]=h[u];h[u]=en;to[++en]=u;nx[en]=h[v];h[v]=en;}void dfs(int u,int f){fa[u]=f;sz[u]=1;dfn[u]=++tim;id[tim]=u;for(int i=h[u];i;i=nx[i]){int v=to[i];if(v==f)continue;dfs(v,u);sz[u]+=sz[v];}out[u]=tim;}int tot,rt_p[N],ls[N*20],rs[N*20],sum[N*20];void ins(int&p,int pre,int l,int r,int pos){p=++tot;ls[p]=ls[pre];rs[p]=rs[pre];sum[p]=sum[pre]+1;if(l==r)return;int mid=(l+r)>>1;if(pos<=mid)ins(ls[p],ls[pre],l,mid,pos);else ins(rs[p],rs[pre],mid+1,r,pos);}int ask(int p,int l,int r,int ql,int qr){if(!p||ql>qr)return 0;if(ql<=l&&r<=qr)return sum[p];int mid=(l+r)>>1,res=0;if(ql<=mid)res+=ask(ls[p],l,mid,ql,qr);if(qr>mid)res+=ask(rs[p],mid+1,r,ql,qr);return res;}inline int qcnt(int u,int L,int R){if(L>R||u==0)return 0;return ask(rt_p[out[u]],1,n,L,R)-ask(rt_p[dfn[u]-1],1,n,L,R);}struct Ask{int l,r,x,id;}a[M];bool cmpx(const Ask&u,const Ask&v){return u.x<v.x;}int qs[N],qe[N];ll ans[M];void solve_light(int x){for(int t=qs[x];t<qe[x];++t){int L=a[t].l,R=a[t].r,qid=a[t].id;ll S=qcnt(x,L,R);ll bad=0;for(int i=h[x];i;i=nx[i]){int v=to[i];if(v==fa[x])continue;int c=qcnt(v,L,R);bad+=1LL*c*(c-1)/2;}ans[qid]=S*(S-1)/2-bad;}}int seq[N],slen,sid[N];int cid;int tag[N];void build_seq(int x){slen=0;static int tmp[N];int tp=1;tmp[1]=x;int cur=0;while(tp){int u=tmp[tp--];++cur;tmp[cur]=u;}static int stk[N],buf[N];int top=1;stk[1]=x;slen=0;while(top){int u=stk[top--];buf[++slen]=u;for(int i=h[u];i;i=nx[i]){int v=to[i];if(v!=fa[u])stk[++top]=v;}}sort(buf+1,buf+slen+1);tag[x]=0;cid=0;for(int i=h[x];i;i=nx[i]){int v=to[i];if(v==fa[x])continue;++cid;top=1;stk[1]=v;while(top){int u=stk[top--];tag[u]=cid;for(int j=h[u];j;j=nx[j]){int w=to[j];if(w!=fa[u])stk[++top]=w;}}}for(int i=1;i<=slen;++i){seq[i]=buf[i];sid[seq[i]]=tag[seq[i]];}}struct Mo{int l,r,id;}mo[M];int mo_cnt;ll cur_sum,cur_tot;int ct[N];inline void add_col(int col){int&c=ct[col];cur_tot++;cur_sum-=1LL*c*(c-1)/2;c++;cur_sum+=1LL*c*(c-1)/2;}inline void del_col(int col){int&c=ct[col];cur_tot--;cur_sum-=1LL*c*(c-1)/2;c--;cur_sum+=1LL*c*(c-1)/2;}void solve_heavy(int x){build_seq(x);mo_cnt=0;for(int t=qs[x];t<qe[x];++t){int L=a[t].l,R=a[t].r,qid=a[t].id;int lpos=lower_bound(seq+1,seq+slen+1,L)-seq;int rpos=upper_bound(seq+1,seq+slen+1,R)-seq-1;if(lpos<=rpos)mo[++mo_cnt]={lpos,rpos,qid};else ans[qid]=0;}if(mo_cnt==0)return;int block=max(1,(int)(slen/sqrt(mo_cnt)));sort(mo+1,mo+mo_cnt+1,[block](const Mo&p,const Mo&q){if(p.l/block!=q.l/block)return p.l/block<q.l/block;return((p.l/block)&1)?p.r<q.r:p.r>q.r;});memset(ct,0,sizeof(int)*(cid+1));cur_sum=cur_tot=0;int l=1,r=0;for(int i=1;i<=mo_cnt;++i){while(l>mo[i].l)add_col(sid[seq[--l]]);while(r<mo[i].r)add_col(sid[seq[++r]]);while(l<mo[i].l)del_col(sid[seq[l++]]);while(r>mo[i].r)del_col(sid[seq[r--]]);ans[mo[i].id]=cur_tot*(cur_tot-1)/2-cur_sum;}}int main(){n=read();m=read();rt=read();for(int i=1;i<n;++i)add(read(),read());dfs(rt,0);for(int i=1;i<=n;++i)ins(rt_p[i],rt_p[i-1],1,n,id[i]);for(int i=1;i<=m;++i)a[i].l=read(),a[i].r=read(),a[i].x=read(),a[i].id=i;sort(a+1,a+m+1,cmpx);for(int i=1;i<=m;++i){if(i==1||a[i].x!=a[i-1].x)qs[a[i].x]=i;if(i==m||a[i].x!=a[i+1].x)qe[a[i].x]=i+1;}for(int x=1;x<=n;++x){if(qs[x]==0)continue;int chd=(x==rt?(int)h[x]==0?0:-1:0);int d=0;for(int i=h[x];i;i=nx[i])if(to[i]!=fa[x])++d;if(d<=B)solve_light(x);else solve_heavy(x);}for(int i=1;i<=m;++i)printf("%lld\n",ans[i]);return 0;}